# PostgreSQL Connection Pool in Node.js

## Installation

```bash
npm install pg
```

## Basic Pool Setup

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  // Connection settings
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                    // Maximum connections in pool
  min: 2,                     // Minimum idle connections maintained
  idleTimeoutMillis: 30000,   // Remove idle connections after 30s
  connectionTimeoutMillis: 5000, // Fail if can't connect within 5s

  // Query timeout (requires pg >= 8.x)
  statement_timeout: 10000,   // Kill queries running over 10s
  query_timeout: 10000,       // Client-level query timeout

  // SSL (for production/cloud databases)
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true, ca: process.env.DB_SSL_CERT }
    : false,
});

module.exports = pool;
```

## Error Handling & Monitoring

```javascript
// db/pool.js (extended)
const { Pool } = require('pg');

const pool = new Pool({ /* config above */ });

// Handle unexpected errors on idle clients
// Without this, errors crash the process
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client:', err.message);
  // Don't exit - pool will remove the broken client automatically
});

// Optional: Monitor pool lifecycle
pool.on('connect', (client) => {
  console.debug(`New client connected. Pool size: ${pool.totalCount}`);
});

pool.on('acquire', (client) => {
  console.debug(`Client acquired. Idle: ${pool.idleCount}, Waiting: ${pool.waitingCount}`);
});

pool.on('remove', (client) => {
  console.debug(`Client removed. Pool size: ${pool.totalCount}`);
});

module.exports = pool;
```

## Query Wrapper with Error Handling

```javascript
// db/query.js
const pool = require('./pool');

/**
 * Execute a query with automatic connection management
 * @param {string} text - SQL query
 * @param {Array} params - Query parameters
 * @returns {Promise<QueryResult>}
 */
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;

    // Log slow queries
    if (duration > 1000) {
      console.warn('Slow query detected:', {
        text,
        duration: `${duration}ms`,
        rows: result.rowCount,
      });
    }

    return result;
  } catch (err) {
    // Enrich error with query context
    err.query = text;
    err.queryParams = params;
    throw err;
  }
}

/**
 * Execute multiple queries in a transaction
 * @param {Function} callback - Receives client, executes queries
 */
async function withTransaction(callback) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    // ALWAYS release - prevents pool exhaustion
    client.release();
  }
}

/**
 * Execute queries requiring a dedicated client
 * Useful for LISTEN/NOTIFY or session-level settings
 */
async function withClient(callback) {
  const client = await pool.connect();
  try {
    return await callback(client);
  } finally {
    client.release();
  }
}

module.exports = { query, withTransaction, withClient };
```

## Usage Examples

```javascript
// routes/users.js
const { query, withTransaction } = require('../db/query');

// Simple query
async function getUser(id) {
  const { rows } = await query(
    'SELECT id, name, email FROM users WHERE id = $1',
    [id]
  );
  return rows[0] ?? null;
}

// Transaction example
async function transferFunds(fromId, toId, amount) {
  return withTransaction(async (client) => {
    // Both queries use the same connection/transaction
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    const { rows } = await client.query(
      'INSERT INTO transfers (from_id, to_id, amount) VALUES ($1, $2, $3) RETURNING *',
      [fromId, toId, amount]
    );

    return rows[0];
  });
}
```

## Graceful Shutdown

```javascript
// server.js
const pool = require('./db/pool');

async function shutdown(signal) {
  console.log(`Received ${signal}. Shutting down gracefully...`);

  try {
    // Stop accepting new connections, wait for active ones to finish
    await pool.end();
    console.log('Database pool closed');
    process.exit(0);
  } catch (err) {
    console.error('Error during shutdown:', err);
    process.exit(1);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

## Health Check Endpoint

```javascript
// routes/health.js
const pool = require('../db/pool');

async function healthCheck(req, res) {
  try {
    const start = Date.now();
    await pool.query('SELECT 1');

    res.json({
      status: 'healthy',
      database: {
        latency: `${Date.now() - start}ms`,
        totalConnections: pool.totalCount,
        idleConnections: pool.idleCount,
        waitingRequests: pool.waitingCount,
      },
    });
  } catch (err) {
    res.status(503).json({
      status: 'unhealthy',
      error: err.message,
    });
  }
}
```

## Key Configuration Guidelines

| Setting | Development | Production |
|---|---|---|
| `max` | 5–10 | 10–25 (tune per load) |
| `min` | 0–2 | 2–5 |
| `idleTimeoutMillis` | 10,000 | 30,000 |
| `connectionTimeoutMillis` | 3,000 | 5,000 |
| `statement_timeout` | 30,000 | 10,000 |

**Critical rules:**
- Always `release()` clients in a `finally` block — leaked clients exhaust the pool
- Set `max` based on your PostgreSQL `max_connections` limit (leave headroom for other services)
- Use `withTransaction` for multi-step operations to ensure atomicity
- The `pool.on('error')` handler is **required** to prevent unhandled rejections from crashing your app
